/**
 * Playwright config — visual-regression baselines only.
 *
 * The broad review screenshots are generated by `qa/run.mjs` and are transient.
 * *These* are the committed baselines: a deliberately small set of routes whose
 * pixels are asserted, so a genuine visual regression fails a test instead of
 * quietly overwriting a review PNG.
 *
 *   pnpm qa:visual:update     # regenerate baselines (review the diff!)
 *   pnpm qa:visual            # assert against them
 *
 * `testMatch` is not optional here. The default collector takes every
 * `*.test.*` and `*.spec.*` under `testDir`, and `tests/unit/**` holds the
 * *Vitest* suites (`pnpm test:showcase`) — so `qa:baseline` used to die before
 * the first assertion with "Cannot find package 'vitest' imported from
 * tests/unit/summary-budget.test.ts". Two runners, two file conventions: the
 * baselines are the `.spec.mjs` files, and only those.
 */

import path from "node:path";
import { defineConfig, devices } from "@playwright/test";

const baseURL = process.env.LUC_QA_BASE_URL ?? "http://127.0.0.1:3000";

export default defineConfig({
  testDir: "./tests",
  testMatch: "**/*.spec.mjs",
  snapshotDir: path.resolve(import.meta.dirname, "../../artifacts/baselines"),
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: [["list"]],
  timeout: 90_000,
  expect: {
    timeout: 15_000,
    toHaveScreenshot: {
      // Anti-aliasing and font rasterisation differ between machines; the point
      // is to catch layout, colour and spacing regressions, not subpixels.
      maxDiffPixelRatio: 0.02,
      threshold: 0.25,
      animations: "disabled",
      caret: "hide",
    },
  },
  use: {
    baseURL,
    viewport: { width: 1440, height: 1000 },
    deviceScaleFactor: 1,
    colorScheme: "dark",
    trace: "off",
    video: "off",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"], viewport: { width: 1440, height: 1000 } } }],
});
